# Expected values are SymPy's outputs for the same calls (Finitely presented groups (polyhedron)).

skip_unless_full_tests()

skip_on_cran()

.bt <- new.env(parent = asNamespace("symcompR"))
eval(parse(text = r"---(NULL
)---"), envir = .bt)
.run <- function(code) {
  e <- .bt
  NULL
  gsub("\n", " ", get("fp_str", envir = .bt)(eval(parse(text = code), envir = e)), fixed = TRUE)
}
.setup <- function(code) invisible(eval(parse(text = code), envir = .bt))
.err <- function(code) tryCatch({ .run(code); "no error" }, error = function(e) gsub("\n", " ", conditionMessage(e), fixed = TRUE))

test_that("Finitely presented groups (polyhedron) match SymPy", {
  expect_equal(.err("Polyhedron(list(\"a\", \"b\"), pgroup = list(Permutation(0)))"), "Permutation size unequal to number of corners.")
  .setup("pg <- list(Permutation(list(c(0, 7, 2, 5), c(6, 1, 4, 3))), Permutation(list(c(0, 7, 1, 6), c(5, 2, 4, 3))), Permutation(list(c(3, 6, 0, 5), c(4, 1, 7, 2))), Permutation(list(c(7, 4, 5), c(1, 3, 0), 2, 6)), Permutation(list(c(1, 3, 2), c(7, 6, 5), 4, 0)), Permutation(list(c(4, 7, 6), c(2, 0, 3), 1, 5)), Permutation(list(c(1, 2, 0), c(4, 5, 6), 3, 7)), Permutation(list(c(4, 2), c(0, 6), c(3, 7), c(1, 5))), Permutation(list(c(3, 5), c(7, 1), c(2, 6), c(0, 4))), Permutation(list(c(2, 5), c(1, 6), c(0, 4), c(3, 7))), Permutation(list(c(4, 3), c(7, 0), c(5, 1), c(6, 2))), Permutation(list(c(4, 1), c(0, 5), c(6, 2), c(7, 3))), Permutation(list(c(7, 2), c(3, 6), c(0, 4), c(1, 5))), Permutation(0:7)); corners <- lapply(LETTERS[1:8], Symbol); C <- Polyhedron(corners, polyhedron_faces(\"cube\"), pg)")
  expect_equal(.run("poly_edges(C)"), "{(0, 1), (0, 3), (0, 4), (1, 2), (1, 5), (2, 3), (2, 6), (3, 7), (4, 5), (4, 7), (5, 6), (6, 7)}")
  expect_equal(.run("poly_faces(C)"), "{(0, 1, 2, 3), (0, 1, 5, 4), (0, 3, 7, 4), (1, 2, 6, 5), (2, 3, 7, 6), (4, 5, 6, 7)}")
  expect_equal(.run("poly_corners(C)"), "(A, B, C, D, E, F, G, H)")
  expect_equal(.run("poly_size(C)"), "8")
  expect_equal(.run("poly_pgroup(C)"), "PermutationGroup([     (0 7 2 5)(1 4 3 6),     (0 7 1 6)(2 4 3 5),     (0 5 3 6)(1 7 2 4),     (0 1 3)(4 5 7),     (1 3 2)(5 7 6),     (0 3 2)(4 7 6),     (7)(0 1 2)(4 5 6),     (0 6)(1 5)(2 4)(3 7),     (0 4)(1 7)(2 6)(3 5),     (0 4)(1 6)(2 5)(3 7),     (0 7)(1 5)(2 6)(3 4),     (0 5)(1 4)(2 6)(3 7),     (0 4)(1 5)(2 7)(3 6)])")
  expect_equal(.run("{for (i in 0:2) poly_rotate(C, C$pgroup$gens[[i + 1]]^2); poly_corners(C)}"), "(A, B, C, D, E, F, G, H)")
  expect_equal(.run("{for (i in 3:6) poly_rotate(C, C$pgroup$gens[[i + 1]]^2); poly_corners(C)}"), "(A, B, C, D, E, F, G, H)")
  expect_equal(.run("{poly_rotate(C, 1); poly_corners(C)}"), "(H, G, E, F, D, C, A, B)")
  expect_equal(.err("poly_rotate(C, Permutation(c(0, 1)))"), "Polyhedron and Permutation sizes differ.")
  expect_equal(.run("I(poly_array_form(C))"), "[7, 6, 4, 5, 3, 2, 0, 1]")
  expect_equal(.run("poly_cyclic_form(C)"), "[[0, 7, 1, 6], [2, 4, 3, 5]]")
  expect_equal(.run("{poly_reset(C); poly_corners(C)}"), "(A, B, C, D, E, F, G, H)")
  expect_equal(.run("fp_str(C)"), "Polyhedron((A, B, C, D, E, F, G, H), ((0, 1, 2, 3), (0, 1, 5, 4), (0, 3, 7, 4), (1, 2, 6, 5), (2, 3, 7, 6), (4, 5, 6, 7)), ((0 7 2 5)(1 4 3 6), (0 7 1 6)(2 4 3 5), (0 5 3 6)(1 7 2 4), (0 1 3)(4 5 7), (1 3 2)(5 7 6), (0 3 2)(4 7 6), (7)(0 1 2)(4 5 6), (0 6)(1 5)(2 4)(3 7), (0 4)(1 7)(2 6)(3 5), (0 4)(1 6)(2 5)(3 7), (0 7)(1 5)(2 6)(3 4), (0 5)(1 4)(2 6)(3 7), (0 4)(1 5)(2 7)(3 6), (7)))")
  expect_equal(.run("fp_str(tetrahedron())"), "Polyhedron((0, 1, 2, 3), ((0, 1, 2), (0, 2, 3), (0, 1, 3), (1, 2, 3)), ((1 2 3), (3)(0 1 2), (0 3 2), (0 3 1), (0 1)(2 3), (0 2)(1 3), (0 3)(1 2)))")
